# @@ src/psa-categories.ps1 @@
$ErrorActionPreference = 'Stop'

function Get-Prop { param($o, [string]$n) if ($null -eq $o) { return $null }; if ($o -is [System.Collections.IDictionary]) { if ($o.Contains($n)) { return $o[$n] }; return $null }; $p = $o.PSObject.Properties[$n]; if ($p) { return $p.Value }; return $null }
function Read-Json { param($v) if ($null -eq $v) { return $null }; if ($v -isnot [string]) { return $v }; if (-not $v.Trim()) { return $null }; try { return ($v | ConvertFrom-Json -NoEnumerate) } catch { return $null } }
$stopState = @{ done = $false; ticket = '' }
$warnings = New-Object System.Collections.ArrayList
function Get-AllWarnings {
    param($Own)
    $all = New-Object System.Collections.ArrayList
    foreach ($w in @(@($Own) + @($PsaState.Warnings))) { $t = [string]$w; if ($t -and -not $all.Contains($t)) { $null = $all.Add($t) } }
    return @($all)
}
function Stop-Write {
    param([string]$Status, [string]$Why)
    $stopState.done = $true
    Set-NodeOutput ([ordered]@{ status = $Status; message = $Why; public_note = ''; internal_note = "Auto-categorize stopped: $Why"; ticket_id = $stopState.ticket; actions = @(); warnings = @(Get-AllWarnings $warnings) })
    throw $Why
}
trap { if (-not $stopState.done) { $stopState.done = $true; Set-NodeOutput ([ordered]@{ status = 'error'; message = [string]$_.Exception.Message; public_note = ''; internal_note = "Auto-categorize failed while writing to the PSA: $($_.Exception.Message)"; ticket_id = $stopState.ticket; actions = @(); warnings = @(Get-AllWarnings $warnings) }) }; break }

$req = Read-Json (Get-NodeInput -Name 'request')
$state = Read-Json (Get-NodeInput -Name 'state')
$aiRaw = Get-NodeInput -Name 'judgment'
if ($null -eq $req -or $null -eq $state) { Stop-Write 'error' 'The ticket details from the first step are missing. Run the workflow from the start.' }
$id = [string](Get-Prop $req 'ticketId'); $num = [string](Get-Prop $req 'number'); $stopState.ticket = $num
$actions = New-Object System.Collections.ArrayList
foreach ($w in @(Read-Json (Get-NodeInput -Name 'warnings_json'))) { if ($w) { $null = $warnings.Add([string]$w) } }
foreach ($a in @(Read-Json (Get-NodeInput -Name 'actions_json'))) { if ($a) { $null = $actions.Add([string]$a) } }
$confirm = (Get-Prop $req 'confirm') -eq $true
$addNote = (Get-Prop $req 'addNote') -ne $false
$minConf = 0.7; try { $minConf = [double](Get-Prop $req 'minConfidence') } catch { }
$labels = @($state.labels)
$open = @(@($state.open) | ForEach-Object { [int]$_ })
$counts = [ordered]@{ fieldsSet = 0; notesWritten = 0 }
function Complete-Run {
    param([string]$Status, [string]$Message, [string]$Internal, $Suggested)
    Set-NodeOutput ([ordered]@{
            status = $Status; message = $Message; public_note = ''; internal_note = $Internal; ticket_id = $num
            suggested = $Suggested; counts = $counts; actions = @($actions); warnings = @(Get-AllWarnings $warnings)
        })
}

$skip = [string](Get-Prop $req 'skip')
if ($skip) { Complete-Run 'success' $skip $skip $null; return }

# ---- the AI's picks, checked against the PSA's own list ----
$ai = $null; $aiText = [string]$aiRaw
if ($aiRaw -and $aiRaw -isnot [string]) { $ai = $aiRaw }
elseif ($aiText -match '(?s)\{.*\}') { try { $ai = $Matches[0] | ConvertFrom-Json } catch { $ai = $null } }
$conf = 0.0; $reason = ''
$picks = New-Object string[] $labels.Count
if ($null -eq $ai) { $null = $warnings.Add('The AI step gave no readable answer, so no category was chosen.') }
else {
    try { $conf = [double](Get-Prop $ai 'confidence') } catch { $conf = 0.0 }
    $reason = [string](Get-Prop $ai 'reason')
    $raw = @(Get-Prop $ai 'picks')
    # Walk down from the fixed levels: each pick must be a child of the level above it.
    $list = @($state.options)
    for ($i = 0; $i -lt $labels.Count; $i++) {
        if ($open -notcontains $i) {
            if ($i -lt $open[0]) { $n = Find-CatChild $list ([string]$state.current[$i].name); $list = $(if ($n) { @($n.children) } else { @() }) }
            continue
        }
        $k = [array]::IndexOf($open, $i)
        $name = $(if ($k -ge 0 -and $k -lt $raw.Count) { ([string]$raw[$k]).Trim() } else { '' })
        if (-not $name) { break }
        $n = Find-CatChild $list $name
        if ($null -eq $n) { $null = $warnings.Add("The AI picked '$name' as the $($labels[$i]), which isn't in the list here, so it and anything below it were left out."); break }
        $picks[$i] = [string]$n.name; $list = @($n.children)
    }
}
$chosen = @(for ($i = 0; $i -lt $labels.Count; $i++) { if ($picks[$i]) { "$($labels[$i]) '$($picks[$i])'" } })
$suggested = [ordered]@{}; for ($i = 0; $i -lt $labels.Count; $i++) { if ($picks[$i]) { $suggested[$labels[$i]] = $picks[$i] } }
$confText = '{0:0.00}' -f $conf

if (-not $chosen.Count) {
    $msg = "No category was chosen for ticket $num, so nothing was changed."
    Complete-Run 'incomplete' $msg "$msg$(if ($reason) { " AI note: $reason" })" $null
    return
}
$sure = $conf -ge $minConf
$line = "Ticket $($num): $($chosen -join ', ') (confidence $confText)."
if (-not $confirm) {
    $msg = "Preview only, nothing was changed. $(if ($sure) { 'Would set' } else { 'Would suggest, but not set (confidence below ' + ('{0:0.00}' -f $minConf) + ')' }): $line"
    Complete-Run 'pending_confirmation' $msg "$msg$(if ($reason) { " Reason: $reason" })" $suggested
    return
}

# ---- confirmed: set the blank fields when sure, and note the result either way ----
$conn = Connect-Psa -Psa ([string](Get-Prop $req 'psa'))
$psaName = Get-PsaName
$set = @()
if ($sure) {
    try { $set = @(Set-PsaCategory -Id $id -State $state -Picks $picks) }
    catch { $null = $warnings.Add("$psaName didn't accept the category, so no field was changed: $($_.Exception.Message)"); $sure = $false }
}
if ($set.Count) { $counts.fieldsSet = $set.Count; $null = $actions.Add("Set the $($set -join ' and ') on ticket $num.") }
$internal = $(if ($set.Count) {
        "Auto-categorized ticket $($num): set the $($set -join ', ') (confidence $confText). Only fields that were blank were set.$(if ($reason) { " Reason: $reason" })"
    }
    else {
        "Suggested category for ticket $($num): $($chosen -join ', ') (confidence $confText). Not applied$(if ($conf -lt $minConf) { ' because the confidence is below ' + ('{0:0.00}' -f $minConf) } else { ' because the PSA refused it' }); a technician can set it.$(if ($reason) { " Reason: $reason" })"
    })
if ($addNote) {
    try {
        $r = Add-PsaNote -Id $id -Text $internal -Title 'Auto-categorize' -Internal -Marker "auto-categorize-$(if ($set.Count) { 'set' } else { 'suggest' })"
        if ($r -eq 'written') { $counts.notesWritten = 1; $null = $actions.Add("Added the internal note to ticket $num.") }
        else { $null = $actions.Add("The internal note was already on ticket $num, so it was not added again.") }
    }
    catch { $null = $warnings.Add("The internal note couldn't be added to ticket $($num): $($_.Exception.Message)") }
}
$status = $(if ($set.Count) { 'success' } else { 'incomplete' })
$msg = $(if ($set.Count) { "Set the $($set -join ' and ') on ticket $num." } else { "Suggested $($chosen -join ', ') for ticket $num but changed no field." })
Complete-Run $status $msg $internal $suggested
